const input = $json.body || $json;

const payload = {
  business_name: String(input.business_name || input.businessName || '').trim(),
  industry: String(input.industry || input.niche || '').trim(),
  product: String(input.product || '').trim(),
  audience: String(input.audience || '').trim(),
  location: String(input.location || input.geo || '').trim(),
  budget: String(input.budget || '').trim(),
  goal: String(input.goal || 'get leads').trim(),
};

const required = ['business_name', 'industry', 'product', 'audience', 'location', 'budget', 'goal'];
const missing = required.filter((key) => !payload[key]);
if (missing.length) {
  return [{ json: { ok: false, statusCode: 400, error: 'Missing required fields', missing, received: input } }];
}

const system = `You are an AI Marketing Analyst.

Your job:
- analyze the business and product;
- find growth points;
- propose advertising hypotheses;
- create offer variants;
- propose ad creative ideas;
- give next actions.

Work like a practical performance marketer. Answer in Russian, be specific, avoid generic advice.

Return only valid JSON. No Markdown. No explanations before or after JSON.

Strict schema:
{
  "business_analysis": "string up to 700 characters, in Russian",
  "target_audience": ["exactly 4 short Russian audience segments as strings"],
  "marketing_hypotheses": ["exactly 3 Russian hypotheses as strings"],
  "offer_variants": ["exactly 5 Russian offers as strings"],
  "creative_ideas": ["exactly 5 Russian ad creative ideas as strings"],
  "recommended_actions": ["exactly 7 Russian next actions as strings"]
}

Arrays must contain strings, not objects. Do not use newline characters inside JSON strings.`;

const prompt = `Analyze the business and prepare a marketing analysis in Russian.

Input:
- Business name: ${payload.business_name}
- Industry: ${payload.industry}
- Product description: ${payload.product}
- Target audience: ${payload.audience}
- Geography: ${payload.location}
- Advertising budget: ${payload.budget}
- Main goal: ${payload.goal}

Required output:
1. Briefly assess the business, product, market and growth points.
2. Split the target audience into clear segments.
3. Propose 3 advertising hypotheses.
4. Propose 5 offer variants.
5. Propose 5 ad creative ideas.
6. Give a 7-day action plan.

Return strictly JSON according to the schema.`;

const vibe_body = {
  type: 'text',
  model: 'claude-opus-5',
  system,
  prompt,
  max_tokens: 3000,
  effort: 'medium',
  thinking: false,
  strict: true,
  idempotency_key: 'marketing-analysis-' + Date.now() + '-' + Math.random().toString(16).slice(2),
};

return [{ json: { ok: true, payload, vibe_body } }];

function stripFences(value) {
  return String(value || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
}

function extractJsonObject(value) {
  const cleaned = stripFences(value);
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) return cleaned.slice(start, end + 1);
  return cleaned;
}

function escapeControlCharsInsideStrings(value) {
  let out = '';
  let inString = false;
  let escaped = false;
  for (const char of value) {
    if (escaped) {
      out += char;
      escaped = false;
      continue;
    }
    if (char === '\\') {
      out += char;
      escaped = true;
      continue;
    }
    if (char === '"') {
      inString = !inString;
      out += char;
      continue;
    }
    if (inString && char === '\n') out += '\\n';
    else if (inString && char === '\r') out += '\\r';
    else if (inString && char === '\t') out += '\\t';
    else out += char;
  }
  return out;
}

function parseJson(value) {
  const candidate = extractJsonObject(value);
  try { return JSON.parse(candidate); } catch (_) {}
  return JSON.parse(escapeControlCharsInsideStrings(candidate));
}

const raw = $json.text || $json.response?.text || '';
const parsed = parseJson(raw);
let estimate = {};
try { estimate = $items('Vibe - Estimate Cost')[0].json; } catch (_) {}

return [{
  json: {
    ok: true,
    business_analysis: parsed.business_analysis || '',
    target_audience: parsed.target_audience || [],
    marketing_hypotheses: parsed.marketing_hypotheses || [],
    offer_variants: parsed.offer_variants || [],
    creative_ideas: parsed.creative_ideas || [],
    recommended_actions: parsed.recommended_actions || [],
    raw_model_output: raw,
    estimate,
    vibe_meta: {
      generation_id: $json.generation_id,
      model: $json.model,
      usage: $json.usage,
      cost: $json.cost,
      reserved: $json.reserved,
      refunded: $json.refunded,
      balance_after: $json.balance_after,
    },
  },
}];

const details = $json.error?.message || $json.message || JSON.stringify($json).slice(0, 1200);
return [{
  json: {
    ok: false,
    statusCode: $json.statusCode || 502,
    error: 'VibeMarketolog API request failed',
    details,
    hint: 'Check the API key in HTTP nodes: Authorization: Bearer PASTE_VIBE_API_KEY_HERE. The key must have generate scopes and enough balance.',
  },
}];
